  (201, 'seochon', '토속촌', '삼계탕', array['혼밥', '팀 회식'], '경복궁 인근 삼계탕으로 유명한 곳', null, null, '경복궁 인근', 201),
  (202, 'seongsu', '성수다락', '오므라이스', array['데이트', '혼밥'], '오므라이스와 매콤 크림 파스타, 찹스테이크 리조또가 대표 메뉴로 소개된 양식 식당입니다.', null, '네이버 예약이 가능하다고 안내되어 있습니다.', '서울 성동구 뚝섬로9길 20 2층', 75),
  (203, 'seongsu', '오사이초밥 성수점', '초밥', array['데이트', '혼밥'], '런치 22,000원, 디너 33,000원대 구성으로 소개된 합리적인 가격의 초밥 오마카세입니다.', null, '네이버 예약이나 캐치테이블로 예약하며, 주차는 어렵다고 안내되어 있습니다.', '서울 성동구 연무장3길 9-14 1층', 76),
  (204, 'seongsu', '성수 스시준', '오마카세', array['데이트'], '기념일 자리로 많이 찾는다고 알려진 스시 오마카세입니다. 월요일은 휴무입니다.', null, '캐치테이블 앱으로 예약하며, 최소 1~2주 전에는 잡는 편이 좋다는 후기가 있습니다. 브레이크타임은 15:00~17:00입니다.', '서울 성동구 연무장19길 6 1층', 77),
  (205, 'seongsu', '스시 오오모토', '오마카세', array['데이트'], '뚝섬역 근처 건물 4층에 있는 스시 오마카세로, 한 팀당 1병 콜키지 프리라는 소개가 있습니다.', null, '캐치테이블에서 예약하며, 빈자리가 나면 알림이 와서 선착순으로 잡는 방식이라는 후기가 있습니다.', '서울 성동구 상원1길 39-1 4층', 78),
  (206, 'seongsu', '성수일구', '이자카야', array['데이트', '팀 회식'], '뚝도시장 먹자골목에서 늦게까지 문을 여는 이자카야·사시미 술집입니다. 월요일은 휴무입니다.', null, null, '서울 성동구 성덕정17길 3-1 1층', 79),
  (207, 'seongsu', '성수포차', '포차', array['팀 회식'], '새벽 4시까지 운영하는 것으로 알려진 실내 포차입니다. 테이블 수가 많지 않다는 후기가 있습니다.', null, null, '서울 성동구 성덕정17길 4 1층', 80),
