  (209, 'seongsu', '사위식당 성수점', '낙곱새', array['혼밥', '팀 회식'], '낙곱새를 13,000원, 2인 세트 33,000원에 내는 가성비 식당으로 소개됩니다.', null, null, null, 82),
  (210, 'seongsu', '노이 성수점', '쌀국수', array['혼밥'], '진한 육수의 쌀국수로 소개되는 곳입니다.', '인기 시간대에는 웨이팅이 잦다는 소개가 있어 오픈 시간에 맞춰 가는 방법이 권해집니다.', null, null, 83),
  (211, 'seongsu', '성수일미락', '목살', array['데이트', '팀 회식'], '소금누룩으로 숙성한 목살과 통삼겹이 대표 메뉴이고, 직원이 끝까지 구워준다고 소개됩니다.', null, null, '서울 성동구 상원6나길 22-20', 84),
