  (216, 'yeonnam', '라멘롱시즌', '라멘', array['데이트', '혼밥'], '연남동 라멘집으로 캐치테이블 웨이팅이 길기로 알려져 있습니다. 월요일과 화요일은 휴무입니다.', '오픈 전에 미리 캐치테이블 웨이팅을 걸어야 한다는 후기가 있습니다. 오전 11시 30분 오픈으로 알려져 있습니다.', null, null, 199),
  (217, 'yeonnam', '연남물갈비', '삼겹살', array['데이트', '팀 회식'], '물갈비와 볶음밥으로 알려진 연남동 고깃집입니다.', '현장 웨이팅이 있다는 후기가 있습니다.', '네이버 예약이 가능하다는 후기가 있습니다.', null, 200),
  (218, 'yeonnam', '사루카메', '라멘', array['데이트', '혼밥'], '바지락라멘 등을 내는 라멘집으로, 미쉐린 가이드 빕 구르망에 소개되었습니다.', '대기 줄이 길다는 후기가 있습니다.', '예약 가능 여부는 출처마다 달라 방문 전에 확인이 필요합니다.', '서울 마포구 연남로 15', 201),
  (219, 'yeonnam', '월량관', '중식', array['데이트', '팀 회식'], '차우셔우, 도삭볶음면, 가지깐풍, 샤오롱바오 등을 내는 연남동 중식당입니다.', null, null, '서울 마포구 동교로46길 10', 202),
